def generate_defect_summary(defects):
    summary = {'Total': len(defects), 'Open': 0, 'Closed': 0, 'Critical': 0}
    for d in defects:
        if d['Status'] == 'Open': summary['Open'] += 1
        if d['Status'] == 'Closed': summary['Closed'] += 1
        if d['Severity'] == 'Critical': summary['Critical'] += 1
    return summary

