// src/test/java/stepdefinitions/LoginSteps.java
package stepdefinitions;

import io.cucumber.java.en.Given;
import io.cucumber.java.en.When;
import io.cucumber.java.en.Then;
import io.cucumber.java.Before;
import io.cucumber.java.After;
import org.junit.Assert;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import pages.LoginPage;
import pages.DashboardPage;

public class LoginSteps {
    private WebDriver driver;
    private LoginPage loginPage;
    private DashboardPage dashboardPage;

    @Before("@ui")
    public void setUp() {
        // Setup WebDriver for UI tests
        System.setProperty("webdriver.chrome.driver", "path/to/chromedriver");
        driver = new ChromeDriver();
        driver.manage().window().maximize();
    }

    @After("@ui")
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }

    @Given("the user is on the login page")
    public void userOnLoginPage() {
        loginPage = new LoginPage(driver);
        loginPage.navigateTo();
    }

    @Given("the user is logged in")
    public void userIsLoggedIn() {
        // Reuse existing steps through method calls
        userOnLoginPage();
        loginPage.loginAs("testuser", "password123");
        verifyRedirectToDashboard();
    }

    @When("the user logs in with username {string} and password {string}")
    public void userLogsIn(String username, String password) {
        loginPage.loginAs(username, password);
    }

    @When("the user attempts to log in with invalid credentials")
    public void userAttemptsInvalidLogin() {
        loginPage.loginAs("wronguser", "wrongpass");
    }

    @Then("the user should be redirected to the dashboard")
    public void verifyRedirectToDashboard() {
        dashboardPage = new DashboardPage(driver);
        Assert.assertTrue("Should be on dashboard", 
            dashboardPage.isCurrentPage());
    }

    @Then("a welcome message {string} should be displayed")
    public void verifyWelcomeMessage(String expectedMessage) {
        String actualMessage = dashboardPage.getWelcomeMessage();
        Assert.assertEquals("Welcome message matches", 
            expectedMessage, actualMessage);
    }

    @Then("an error message should be displayed")
    public void verifyErrorMessageDisplayed() {
        Assert.assertTrue("Error message should be displayed", 
            loginPage.isErrorDisplayed());
    }

    @Then("the error message should contain {string}")
    public void verifyErrorMessageContains(String expectedText) {
        String errorText = loginPage.getErrorMessage();
        Assert.assertTrue("Error message contains expected text", 
            errorText.contains(expectedText));
    }

    @Then("the user should remain on the login page")
    public void verifyRemainOnLoginPage() {
        Assert.assertTrue("Should remain on login page", 
            loginPage.isCurrentPage());
    }

    // Example with DataTable for multiple test cases
    @When("the user attempts to log in with the following credentials")
    public void loginWithMultipleCredentials(io.cucumber.datatable.DataTable dataTable) {
        var credentials = dataTable.asMaps();

        for (var creds : credentials) {
            String username = creds.get("username");
            String password = creds.get("password");
            String expected = creds.get("expected");

            loginPage.loginAs(username, password);

            if ("success".equals(expected)) {
                Assert.assertTrue("Login should succeed", 
                    new DashboardPage(driver).isCurrentPage());
                // Logout for next iteration
                dashboardPage.logout();
                // Navigate back to login
                loginPage.navigateTo();
            } else {
                Assert.assertTrue("Should stay on login page", 
                    loginPage.isCurrentPage());
                Assert.assertTrue("Error should be displayed", 
                    loginPage.isErrorDisplayed());
            }
        }
    }
}

// features/step_definitions/login_steps.js
const { Given, When, Then, Before, After } = require('@cucumber/cucumber');
const { chromium } = require('playwright');
const assert = require('assert');

// Page object (usually in separate file)
class LoginPage {
  constructor(page) {
    this.page = page;
  }

  async navigateTo() {
    await this.page.goto('https://example.com/login');
  }

  async loginAs(username, password) {
    await this.page.fill('#username', username);
    await this.page.fill('#password', password);
    await this.page.click('#login-button');
  }

  async getErrorMessage() {
    return await this.page.textContent('.error');
  }

  async isErrorDisplayed() {
    return await this.page.isVisible('.error');
  }
}

class DashboardPage {
  constructor(page) {
    this.page = page;
  }

  async getWelcomeMessage() {
    return await this.page.textContent('#welcome-message');
  }

  async isCurrentPage() {
    const url = this.page.url();
    return url.includes('/dashboard');
  }
}

// Hooks
Before({ tags: '@ui' }, async function() {
  // Launch browser for each scenario
  this.browser = await chromium.launch({ headless: false });
  this.page = await this.browser.newPage();
});

After({ tags: '@ui' }, async function() {
  if (this.browser) {
    await this.browser.close();
  }
});

// Step definitions
Given('the user is on the login page', async function() {
  this.loginPage = new LoginPage(this.page);
  await this.loginPage.navigateTo();
});

Given('the user is logged in', async function() {
  // Reuse steps
  await this.loginPage?.navigateTo();
  await this.loginPage?.loginAs('testuser', 'password123');

  // Verify
  const dashboardPage = new DashboardPage(this.page);
  const isDashboard = await dashboardPage.isCurrentPage();
  assert.ok(isDashboard, 'Should be redirected to dashboard');
  this.dashboardPage = dashboardPage;
});

When('the user logs in with username {string} and password {string}', 
  async function(username, password) {
    await this.loginPage.loginAs(username, password);
});

When('the user attempts to log in with invalid credentials', async function() {
  await this.loginPage.loginAs('wronguser', 'wrongpass');
});

Then('the user should be redirected to the dashboard', async function() {
  this.dashboardPage = new DashboardPage(this.page);
  const isDashboard = await this.dashboardPage.isCurrentPage();
  assert.ok(isDashboard, 'Should be on dashboard page');
});

Then('a welcome message {string} should be displayed', async function(expectedMessage) {
  const actualMessage = await this.dashboardPage.getWelcomeMessage();
  assert.strictEqual(actualMessage, expectedMessage);
});

Then('an error message should be displayed', async function() {
  const isError = await this.loginPage.isErrorDisplayed();
  assert.ok(isError, 'Error message should be displayed');
});

Then('the error message should contain {string}', async function(expectedText) {
  const errorText = await this.loginPage.getErrorMessage();
  assert.ok(errorText.includes(expectedText), 
    `Expected '${expectedText}' in '${errorText}'`);
});

Then('the user should remain on the login page', async function() {
  const url = this.page.url();
  assert.ok(url.includes('/login'), `Should be on login page, but URL is ${url}`);
});

// Data table example
When('the user attempts to log in with the following credentials', 
  async function(dataTable) {
    const credentials = dataTable.hashes();

    for (const cred of credentials) {
      const { username, password, expected } = cred;

      await this.loginPage.loginAs(username, password);

      if (expected === 'success') {
        const dashboardPage = new DashboardPage(this.page);
        assert.ok(await dashboardPage.isCurrentPage());
        // Logout for next iteration
        await this.page.click('#logout-button');
        await this.loginPage.navigateTo();
      } else {
        assert.ok(await this.loginPage.isErrorDisplayed());
        // Clear for next attempt
        await this.page.reload();
      }
    }
});

