"""
Comprehensive BDD metrics collection and analysis.
Run after each test execution to update dashboards.
"""

import json
import glob
import os
from datetime import datetime
from collections import defaultdict, Counter

class BDDAnalytics:
    def __init__(self, results_dir='reports/', history_file='metrics/history.json'):
        self.results_dir = results_dir
        self.history_file = history_file
        self.current_results = []
        self.historical_data = self.load_history()

    def load_history(self):
        """Load historical metrics for trend analysis."""
        if os.path.exists(self.history_file):
            with open(self.history_file) as f:
                return json.load(f)
        return {'runs': [], 'trends': {}}

    def collect_current_results(self):
        """Parse all test result files."""
        # Parse Behave JSON reports
        for report_file in glob.glob(f'{self.results_dir}/*.json'):
            with open(report_file) as f:
                data = json.load(f)
                self.current_results.extend(data)

        return len(self.current_results)

    def calculate_flakiness(self, days=30):
        """Identify flaky scenarios: those that pass/fail inconsistently."""
        # Group by scenario name across multiple runs
        scenario_runs = defaultdict(list)

        for run in self.historical_data['runs'][-days:]:
            for scenario in run['scenarios']:
                scenario_runs[scenario['name']].append(scenario['status'])

        flaky_scenarios = []
        for name, statuses in scenario_runs.items():
            if len(set(statuses)) > 1:  # Mixed pass/fail
                flaky_rate = statuses.count('failed') / len(statuses)
                if 0.05 < flaky_rate < 0.95:  # Not consistently passing or failing
                    flaky_scenarios.append({
                        'name': name,
                        'flaky_rate': flaky_rate,
                        'runs': len(statuses)
                    })

        return flaky_scenarios

    def calculate_step_reuse(self):
        """Calculate step definition reuse ratio."""
        step_usage = Counter()

        for feature in self.current_results:
            for scenario in feature.get('elements', []):
                for step in scenario.get('steps', []):
                    step_usage[step['name']] += 1

        total_steps = sum(step_usage.values())
        unique_steps = len(step_usage)

        return {
            'reuse_ratio': total_steps / unique_steps if unique_steps > 0 else 0,
            'total_steps': total_steps,
            'unique_steps': unique_steps,
            'most_used': step_usage.most_common(10)
        }

    def calculate_execution_times(self):
        """Calculate execution time statistics."""
        times = []

        for feature in self.current_results:
            for scenario in feature.get('elements', []):
                if 'steps' in scenario:
                    scenario_time = sum(
                        step['result']['duration'] 
                        for step in scenario['steps']
                        if 'duration' in step['result']
                    )
                    times.append(scenario_time)

        if not times:
            return {}

        return {
            'avg_time': sum(times) / len(times),
            'p95_time': sorted(times)[int(len(times) * 0.95)],
            'max_time': max(times),
            'min_time': min(times),
            'total_time': sum(times)
        }

    def generate_dashboard(self):
        """Generate metrics dashboard."""
        metrics = {
            'timestamp': datetime.now().isoformat(),
            'execution_stats': self.calculate_execution_times(),
            'step_reuse': self.calculate_step_reuse(),
            'flaky_scenarios': self.calculate_flakiness()
        }

        return metrics

if __name__ == '__main__':
    analytics = BDDAnalytics()
    analytics.collect_current_results()
    metrics = analytics.generate_dashboard()
    print(json.dumps(metrics, indent=2))

// Simplified simulation of CI feedback loop
class CIPipeline {
  constructor(repository, ciServer) {
    this.repository = repository;
    this.ciServer = ciServer;
    this.notificationChannels = [];
  }

  addNotificationChannel(channel) {
    this.notificationChannels.push(channel);
  }

  async onCommit(commitId, author) {
    console.log(`[${new Date().toISOString()}] Detected commit ${commitId} by ${author}`);

    try {
      // Step 1: Checkout code
      console.log('Checking out code...');
      await this.repository.checkout(commitId);

      // Step 2: Install dependencies
      console.log('Installing dependencies...');
      await this.runCommand('npm install');

      // Step 3: Run build
      console.log('Building application...');
      const buildResult = await this.runCommand('npm run build');

      // Step 4: Run tests
      console.log('Running tests...');
      const testResult = await this.runCommand('npm test');

      // Step 5: Parse results
      const passed = testResult.exitCode === 0;
      const summary = this.parseTestResults(testResult.stdout);

      // Step 6: Generate feedback
      const feedback = {
        commitId,
        author,
        timestamp: new Date().toISOString(),
        buildStatus: passed ? 'success' : 'failure',
        testSummary: summary,
        buildLog: buildResult.stdout.substring(0, 500) + '...',
        artifacts: ['dist/app.js', 'coverage/lcov-report']
      };

      // Step 7: Send notifications
      await Promise.all(
        this.notificationChannels.map(channel => 
          channel.send(feedback)
        )
      );

      console.log(`Feedback sent: ${passed ? '✅ PASSED' : '❌ FAILED'}`);
      return feedback;

    } catch (error) {
      console.error('Pipeline failed:', error);
      // Notify of catastrophic failure
      await this.notificationChannels[0].send({
        commitId,
        author,
        timestamp: new Date().toISOString(),
        buildStatus: 'error',
        error: error.message
      });
    }
  }

  async runCommand(command) {
    // Simulate command execution
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({
          exitCode: Math.random() > 0.2 ? 0 : 1, // 80% success rate
          stdout: 'Test results: 42 passed, 0 failed'
        });
      }, 2000);
    });
  }

  parseTestResults(output) {
    // Simple parser
    const match = output.match(/(\d+) passed, (\d+) failed/);
    return match ? { passed: parseInt(match[1]), failed: parseInt(match[2]) } 
                 : { passed: 0, failed: 0 };
  }
}

// Usage
const pipeline = new CIPipeline(
  { checkout: async (id) => console.log(`Checked out ${id}`) },
  { name: 'Jenkins' }
);

pipeline.addNotificationChannel({
  send: async (feedback) => {
    console.log(`Slack: Build ${feedback.buildStatus}`);
  }
});

pipeline.addNotificationChannel({
  send: async (feedback) => {
    console.log(`Email: Results sent to ${feedback.author}`);
  }
});

// Simulate a commit
pipeline.onCommit('abc123', 'developer@example.com');

// Jenkinsfile (Declarative Pipeline)
pipeline {
    agent any

    tools {
        nodejs 'NodeJS-18'
        maven 'Maven-3.9'
    }

    environment {
        DATABASE_URL = credentials('database-url')
        DOCKER_REGISTRY = 'docker.io/myorg'
    }

    parameters {
        choice(name: 'ENVIRONMENT', choices: ['dev', 'staging', 'prod'], description: 'Deployment environment')
        booleanParam(name: 'SKIP_TESTS', defaultValue: false, description: 'Skip tests?')
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Install Dependencies') {
            steps {
                sh 'npm ci'
            }
        }

        stage('Lint and Type Check') {
            when {
                expression { !params.SKIP_TESTS }
            }
            steps {
                parallel(
                    lint: { sh 'npm run lint' },
                    typeCheck: { sh 'npm run type-check' }
                )
            }
        }

        stage('Unit Tests') {
            when {
                expression { !params.SKIP_TESTS }
            }
            steps {
                sh 'npm run test:unit -- --coverage'
            }
            post {
                always {
                    junit 'reports/*.xml'
                    publishHTML([reportDir: 'coverage', reportFiles: 'index.html', reportName: 'Coverage Report'])
                }
            }
        }

        stage('Integration Tests') {
            when {
                expression { !params.SKIP_TESTS }
            }
            steps {
                sh '''
                    docker-compose -f docker-compose.test.yml up -d
                    npm run test:integration
                    docker-compose -f docker-compose.test.yml down
                '''
            }
        }

        stage('Build') {
            steps {
                sh 'npm run build'
                sh 'docker build -t ${DOCKER_REGISTRY}/myapp:${BUILD_NUMBER} .'
            }
        }

        stage('Security Scan') {
            steps {
                sh 'npm audit'
                sh 'docker scan ${DOCKER_REGISTRY}/myapp:${BUILD_NUMBER}'
            }
        }

        stage('Publish Artifacts') {
            steps {
                sh 'docker push ${DOCKER_REGISTRY}/myapp:${BUILD_NUMBER}'
                archiveArtifacts artifacts: 'dist/**/*', fingerprint: true
            }
        }

        stage('Deploy') {
            when {
                branch 'main'
            }
            steps {
                sh './deploy.sh ${ENVIRONMENT}'
            }
        }
    }

    post {
        always {
            cleanWs()  // Clean workspace after build
        }
        success {
            emailext(
                to: 'team@example.com',
                subject: "Build Successful: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "The build completed successfully. Check the artifacts: ${env.BUILD_URL}"
            )
        }
        failure {
            slackSend(
                color: 'danger',
                message: "Build Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER} (<${env.BUILD_URL}|Open>)"
            )
        }
    }
}

