                    <p>Build: ${env.BUILD_NUMBER}</p>
                    <p>View: <a href="${env.BUILD_URL}">${env.BUILD_URL}</a></p>
                """
            )
        }
        failure {
            slackSend(
                color: '#FF0000',
                message: "Build Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER} (<${env.BUILD_URL}|Open>)"
            )
        }
    }
}

// test-optimization.js - Strategies for test optimization

// 1. Parallel test execution with Jest
module.exports = {
  // Run tests in parallel
  maxWorkers: '50%',

  // Shard tests across multiple CI runners
  shard: process.env.CI ? `${process.env.CI_NODE_INDEX}/${process.env.CI_NODE_TOTAL}` : undefined,

  // Cache test results
  cache: true,
  cacheDirectory: '.jest-cache',

  // Only run tests related to changed files
  changedSince: process.env.CI ? 'main' : undefined,

  // Test coverage thresholds
  coverageThreshold: {
    global: {
      branches: 80,
      functions: 80,
      lines: 80,
      statements: 80
    }
  },

  // Test sequencer for ordering
  testSequencer: './test-sequencer.js'
};

// test-sequencer.js - Custom test ordering
const Sequencer = require('@jest/test-sequencer').default;

class CustomSequencer extends Sequencer {
  sort(tests) {
    // Run critical tests first
    const criticalTests = tests.filter(t => 
      t.path.includes('critical') || 
      t.path.includes('payment') || 
      t.path.includes('auth')
    );

    const otherTests = tests.filter(t => 
      !criticalTests.includes(t)
    );

    return [...criticalTests.sort((a, b) => a.path.localeCompare(b.path)), 
            ...otherTests.sort((a, b) => a.path.localeCompare(b.path))];
  }
}

module.exports = CustomSequencer;

// test-splitter.js - Dynamic test splitting
const { execSync } = require('child_process');
const fs = require('fs');

// Get list of test files
const testFiles = execSync('find tests -name "*.test.js"')
  .toString()
  .trim()
  .split('\n');

// Split into chunks based on timing data
const timingData = JSON.parse(fs.readFileSync('test-timings.json'));
const testWithTimings = testFiles.map(file => ({
  file,
  time: timingData[file] || 1000 // default 1 second
}));

// Sort by time (slowest first)
testWithTimings.sort((a, b) => b.time - a.time);

// Distribute to chunks using greedy algorithm
const NUM_CHUNKS = parseInt(process.env.CI_NODE_TOTAL) || 4;
const chunks = Array(NUM_CHUNKS).fill().map(() => ({ files: [], time: 0 }));

testWithTimings.forEach(test => {
  // Find chunk with smallest total time
  const chunk = chunks.reduce((min, current) => 
    current.time < min.time ? current : min
  );

  chunk.files.push(test.file);
  chunk.time += test.time;
});

// Output chunks for CI
console.log(JSON.stringify(chunks, null, 2));

