# Database seeder for integration tests
class DatabaseSeeder:
    def __init__(self, session):
        self.session = session

    def seed_test_data(self):
        # Create users
        users = UserFactory.create_batch(10)

        # Create products
        products = ProductFactory.create_batch(20)

        # Create orders with payments
        orders = []
        for user in users[:5]:
            order = OrderFactory(
                user=user,
                items=[
                    OrderItemFactory(product=products[i])
                    for i in range(randint(1, 4))
                ]
            )
            orders.append(order)

            PaymentFactory(
                order=order,
                status='completed'
            )

        self.session.add_all(users + products + orders)
        self.session.commit()

        return {
            'users': users,
            'products': products,
            'orders': orders
        }

    def seed_performance_test_data(self, scale=1000):
        """Seed large dataset for performance tests"""
        import time

        start = time.time()

        # Create users in batches
        for i in range(0, scale, 100):
            users = UserFactory.create_batch(min(100, scale - i))
            self.session.add_all(users)
            self.session.flush()

        self.session.commit()

        duration = time.time() - start
        print(f"Seeded {scale} users in {duration:.2f} seconds")

        return duration

// flaky-test-detector.js
const fs = require('fs');
const path = require('path');

class FlakyTestDetector {
  constructor(testResultsDir, historyFile = 'flaky-history.json') {
    this.testResultsDir = testResultsDir;
    this.historyFile = historyFile;
    this.history = this.loadHistory();
  }

  loadHistory() {
    if (fs.existsSync(this.historyFile)) {
      return JSON.parse(fs.readFileSync(this.historyFile, 'utf8'));
    }
    return { testRuns: {}, flakyTests: {} };
  }

  processResults() {
    const files = fs.readdirSync(this.testResultsDir)
      .filter(f => f.endsWith('.xml'));

    const currentRun = {
      timestamp: new Date().toISOString(),
      commit: process.env.COMMIT_SHA || 'unknown',
      results: {}
    };

    for (const file of files) {
      const content = fs.readFileSync(path.join(this.testResultsDir, file), 'utf8');
      const tests = this.parseJUnitXML(content);

      for (const test of tests) {
        const testId = `${test.className}.${test.name}`;
        currentRun.results[testId] = test.status;

        // Update history
        if (!this.history.testRuns[testId]) {
          this.history.testRuns[testId] = [];
        }
        this.history.testRuns[testId].push({
          timestamp: currentRun.timestamp,
          commit: currentRun.commit,
          status: test.status
        });

        // Keep only last 20 runs
        if (this.history.testRuns[testId].length > 20) {
          this.history.testRuns[testId].shift();
        }
      }
    }

    this.detectFlakyTests();
    this.saveHistory();
    return this.generateReport();
  }

  parseJUnitXML(content) {
    // Simple parser - in real world, use xml2js
    const tests = [];
    const testcaseRegex = /<testcase\s+classname="([^"]+)"\s+name="([^"]+)"[^>]*>(.*?)<\/testcase>/gs;
    const failureRegex = /<failure/;
    const errorRegex = /<error/;
    const skippedRegex = /<skipped/;

    let match;
    while ((match = testcaseRegex.exec(content)) !== null) {
      const className = match[1];
      const name = match[2];
      const body = match[3];

      let status = 'passed';
      if (failureRegex.test(body)) status = 'failed';
      else if (errorRegex.test(body)) status = 'error';
      else if (skippedRegex.test(body)) status = 'skipped';

      tests.push({ className, name, status });
    }

    return tests;
  }

  detectFlakyTests() {
    const flakyTests = {};

    for (const [testId, runs] of Object.entries(this.history.testRuns)) {
      if (runs.length < 5) continue;

      const statuses = runs.map(r => r.status);
      const uniqueStatuses = new Set(statuses);

      // Test is flaky if it has both passed and failed/error in recent history
      if (uniqueStatuses.size > 1 && 
          (uniqueStatuses.has('passed') && 
           (uniqueStatuses.has('failed') || uniqueStatuses.has('error')))) {

        // Calculate flakiness rate
        const total = runs.length;
        const passed = statuses.filter(s => s === 'passed').length;
        const failed = statuses.filter(s => s === 'failed' || s === 'error').length;
        const flakinessRate = failed / total;

        flakyTests[testId] = {
          flakinessRate,
          totalRuns: total,
          passed,
          failed,
          lastRun: runs[runs.length - 1],
          history: runs
        };
      }
    }

    this.history.flakyTests = flakyTests;
  }

  generateReport() {
    const report = {
      generated: new Date().toISOString(),
      totalTests: Object.keys(this.history.testRuns).length,
      flakyTests: this.history.flakyTests,
      flakyCount: Object.keys(this.history.flakyTests).length,
      flakyRate: Object.keys(this.history.flakyTests).length / 
                 Object.keys(this.history.testRuns).length,
      recommendations: []
    };

    // Generate recommendations
    for (const [testId, data] of Object.entries(this.history.flakyTests)) {
      if (data.flakinessRate > 0.3) {
        report.recommendations.push({
          test: testId,
          priority: 'HIGH',
          action: 'Fix or quarantine immediately',
          rate: data.flakinessRate
        });
      } else if (data.flakinessRate > 0.1) {
        report.recommendations.push({
          test: testId,
          priority: 'MEDIUM',
          action: 'Investigate root cause',
          rate: data.flakinessRate
        });
      }
    }

    // Write report
    fs.writeFileSync('flaky-test-report.json', JSON.stringify(report, null, 2));
    this.generateHTMLReport(report);

    return report;
  }

  generateHTMLReport(report) {
    const html = `
    <!DOCTYPE html>
    <html>
    <head>
      <title>Flaky Test Report</title>
      <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        .header { background: #333; color: white; padding: 20px; }
        .stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin: 20px 0; }
        .stat-card { background: #f5f5f5; padding: 20px; border-radius: 5px; }
        .high { color: #dc3545; }
        .medium { color: #ffc107; }
        .low { color: #28a745; }
        table { width: 100%; border-collapse: collapse; }
        th, td { padding: 10px; text-align: left; border-bottom: 1px solid #ddd; }
        th { background: #f5f5f5; }
      </style>
    </head>
    <body>
      <div class="header">
        <h1>Flaky Test Report</h1>
        <p>Generated: ${report.generated}</p>
      </div>

      <div class="stats">
        <div class="stat-card">
          <h3>Total Tests</h3>
          <p style="font-size: 24px;">${report.totalTests}</p>
        </div>
        <div class="stat-card">
          <h3>Flaky Tests</h3>
          <p style="font-size: 24px; color: #dc3545;">${report.flakyCount}</p>
        </div>
        <div class="stat-card">
          <h3>Flaky Rate</h3>
          <p style="font-size: 24px;">${(report.flakyRate * 100).toFixed(2)}%</p>
        </div>
      </div>

      <h2>High Priority Recommendations</h2>
      <table>
        <tr>
          <th>Test</th>
          <th>Priority</th>
          <th>Action</th>
          <th>Flakiness Rate</th>
        </tr>
        ${report.recommendations.map(rec => `
        <tr>
          <td>${rec.test}</td>
          <td class="${rec.priority.toLowerCase()}">${rec.priority}</td>
          <td>${rec.action}</td>
          <td>${(rec.rate * 100).toFixed(2)}%</td>
        </tr>
        `).join('')}
      </table>

      <h2>All Flaky Tests</h2>
      <table>
        <tr>
          <th>Test</th>
          <th>Runs</th>
          <th>Passed</th>
          <th>Failed</th>
          <th>Flakiness Rate</th>
        </tr>
        ${Object.entries(report.flakyTests).map(([testId, data]) => `
        <tr>
          <td>${testId}</td>
          <td>${data.totalRuns}</td>
          <td>${data.passed}</td>
          <td>${data.failed}</td>
          <td>${(data.flakinessRate * 100).toFixed(2)}%</td>
        </tr>
        `).join('')}
      </table>
    </body>
    </html>
    `;

    fs.writeFileSync('flaky-test-report.html', html);
  }
}

