// Jenkinsfile - Complete CD Pipeline
pipeline {
    agent any

    tools {
        nodejs 'NodeJS-18'
        docker 'latest'
    }

    environment {
        DOCKER_REGISTRY = 'docker.io/myorg'
        DOCKER_IMAGE = "${DOCKER_REGISTRY}/myapp:${BUILD_NUMBER}"
        STAGING_URL = 'https://staging.example.com'
        PRODUCTION_URL = 'https://example.com'
    }

    stages {
        stage('Commit Stage') {
            parallel {
                stage('Lint') {
                    steps {
                        sh 'npm run lint'
                    }
                }
                stage('Type Check') {
                    steps {
                        sh 'npm run type-check'
                    }
                }
                stage('Unit Tests') {
                    steps {
                        sh 'npm run test:unit -- --coverage'
                    }
                    post {
                        always {
                            junit 'junit.xml'
                            publishHTML([
                                reportDir: 'coverage',
                                reportFiles: 'index.html',
                                reportName: 'Coverage Report'
                            ])
                        }
                    }
                }
                stage('Security Scan') {
                    steps {
                        sh 'npm audit'
                    }
                }
            }
        }

        stage('Build and Package') {
            steps {
                sh 'npm run build'
                sh "docker build -t ${DOCKER_IMAGE} ."
                sh "docker push ${DOCKER_IMAGE}"
            }
        }

        stage('Acceptance Tests') {
            parallel {
                stage('Integration Tests') {
                    steps {
                        sh 'docker-compose -f docker-compose.test.yml up -d'
                        sh 'npm run test:integration'
                        sh 'docker-compose -f docker-compose.test.yml down'
                    }
                }
                stage('API Tests') {
                    steps {
                        sh 'npm run test:api'
                    }
                }
                stage('Performance Tests') {
                    steps {
                        sh 'npm run test:performance'
                    }
                }
            }
        }

        stage('Deploy to Staging') {
            steps {
                sh "./deploy.sh staging ${DOCKER_IMAGE}"
            }
            post {
                success {
                    echo "Deployed to staging: ${STAGING_URL}"
                }
            }
        }

        stage('Smoke Tests on Staging') {
            steps {
                sh "npm run test:smoke -- --url=${STAGING_URL}"
            }
        }

        stage('Manual Approval') {
            when {
                branch 'main'
            }
            steps {
                input(
                    message: 'Deploy to production?',
                    ok: 'Deploy',
                    submitter: 'release-managers',
                    parameters: [
                        string(name: 'VERSION', defaultValue: BUILD_NUMBER, description: 'Version to deploy'),
                        choice(name: 'STRATEGY', choices: ['blue-green', 'canary', 'rolling'], description: 'Deployment strategy')
                    ]
                )
            }
        }

        stage('Deploy to Production') {
            steps {
                script {
                    def strategy = params.STRATEGY ?: 'rolling'
                    sh "./deploy.sh production ${DOCKER_IMAGE} --strategy=${strategy}"
                }
            }
            post {
                success {
                    echo "Deployed to production: ${PRODUCTION_URL}"
                }
            }
        }

        stage('Post-Deployment Verification') {
            parallel {
                stage('Smoke Tests') {
                    steps {
                        sh "npm run test:smoke -- --url=${PRODUCTION_URL}"
                    }
                }
                stage('Health Check') {
                    steps {
                        sh "curl -f ${PRODUCTION_URL}/health"
                    }
                }
                stage('Performance Check') {
                    steps {
                        sh "npm run test:performance -- --url=${PRODUCTION_URL}"
                    }
                }
            }
        }
    }

    post {
        failure {
            emailext(
                to: 'team@example.com',
                subject: "Pipeline Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "The pipeline failed. Check ${env.BUILD_URL} for details."
            )
            slackSend(
                color: '#FF0000',
                message: "Pipeline Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER} (<${env.BUILD_URL}|Open>)"
            )
        }
        success {
            slackSend(
                color: '#00FF00',
                message: "Pipeline Succeeded: ${env.JOB_NAME} - ${env.BUILD_NUMBER} deployed to production"
            )
        }
        always {
            cleanWs()
        }
    }
}

// feature-flags.js
const LaunchDarkly = require('launchdarkly-node-server-sdk');
const Redis = require('ioredis');

class FeatureFlagService {
  constructor() {
    this.client = null;
    this.redis = new Redis(process.env.REDIS_URL);
    this.localCache = new Map();
    this.initialized = false;
  }

  async initialize() {
    // Initialize LaunchDarkly client
    this.client = LaunchDarkly.init(process.env.LAUNCHDARKLY_SDK_KEY);

    await new Promise((resolve, reject) => {
      this.client.once('ready', resolve);
      this.client.once('failed', reject);
    });

    this.initialized = true;
    console.log('Feature flag service initialized');

    // Start background sync
    this.startBackgroundSync();
  }

  async getFlag(flagKey, user, defaultValue = false) {
    if (!this.initialized) {
      return this.getFromCache(flagKey, user.id) || defaultValue;
    }

    try {
      // Evaluate flag for user
      const value = await this.client.variation(flagKey, user, defaultValue);

      // Cache result
      this.cacheValue(flagKey, user.id, value);

      return value;
    } catch (error) {
      console.error(`Error evaluating flag ${flagKey}:`, error);
      return this.getFromCache(flagKey, user.id) || defaultValue;
    }
  }

  async getFlagForUserSegment(flagKey, userId, segment) {
    const user = {
      key: userId,
      custom: {
        segment: segment,
        tier: await this.getUserTier(userId)
      }
    };

    return this.getFlag(flagKey, user, false);
  }

  async getAllFlags(user) {
    if (!this.initialized) {
      return {};
    }

    return this.client.allFlagsState(user);
  }

  cacheValue(flagKey, userId, value) {
    const cacheKey = `flag:${flagKey}:${userId}`;
    this.localCache.set(cacheKey, value);

    // Also cache in Redis with TTL
    this.redis.setex(cacheKey, 300, JSON.stringify(value));
  }

  async getFromCache(flagKey, userId) {
    const cacheKey = `flag:${flagKey}:${userId}`;

    // Check local cache first
    if (this.localCache.has(cacheKey)) {
      return this.localCache.get(cacheKey);
    }

    // Check Redis
    const cached = await this.redis.get(cacheKey);
    if (cached) {
      const value = JSON.parse(cached);
      this.localCache.set(cacheKey, value);
      return value;
    }

    return null;
  }

  async getUserTier(userId) {
    // Get user tier from database
    const user = await db.users.findById(userId);
    return user?.tier || 'free';
  }

  startBackgroundSync() {
    // Refresh cache periodically
    setInterval(() => {
      this.localCache.clear();
    }, 60000); // Clear local cache every minute
  }

  // Flag management methods
  async createFlag(flagKey, description, variations) {
    // This would use LaunchDarkly API
    console.log(`Creating flag: ${flagKey}`);
  }

  async updateFlagTargeting(flagKey, targetingRules) {
    // Update flag targeting rules
    console.log(`Updating targeting for: ${flagKey}`);
  }

  async deleteFlag(flagKey) {
    // Clean up old flag
    console.log(`Deleting flag: ${flagKey}`);
  }
}

// Usage example
class CheckoutService {
  constructor(flagService) {
    this.flags = flagService;
  }

  async processCheckout(userId, cart) {
    const user = { key: userId };

    // Check if new checkout flow is enabled for this user
    const useNewCheckout = await this.flags.getFlag(
      'new-checkout-flow',
      user,
      false
    );

    if (useNewCheckout) {
      return this.processNewCheckout(userId, cart);
    } else {
      return this.processLegacyCheckout(userId, cart);
    }
  }

  async applyDiscount(userId, amount) {
    const user = { key: userId };

    // Check for premium user discount
    const discountPercent = await this.flags.getFlagForUserSegment(
      'premium-discount',
      userId,
      'premium'
    );

    if (discountPercent) {
      return amount * (1 - discountPercent / 100);
    }

    return amount;
  }

  async processNewCheckout(userId, cart) {
    // New checkout implementation
    console.log('Processing with new checkout flow');

    // Feature flags for sub-features
    const flags = await this.flags.getAllFlags({ key: userId });

    if (flags.oneClickCheckout) {
      return this.oneClickCheckout(userId, cart);
    }

    if (flags.savePaymentMethod) {
      await this.savePaymentMethod(userId, cart.paymentMethod);
    }

    return this.standardCheckout(userId, cart);
  }

  processLegacyCheckout(userId, cart) {
    console.log('Processing with legacy checkout flow');
    return this.standardCheckout(userId, cart);
  }

  // ... other methods
}

