// response_time_analysis.js
// Function to calculate percentiles from response time array
function calculatePercentiles(responseTimes, percentiles = [50, 95, 99, 99.9]) {
  // Sort response times in ascending order
  const sorted = [...responseTimes].sort((a, b) => a - b);

  const results = {};

  percentiles.forEach(p => {
    // Calculate index for percentile
    const index = Math.ceil((p / 100) * sorted.length) - 1;
    results[`p${p}`] = sorted[index];
  });

  // Calculate additional statistics
  results.avg = responseTimes.reduce((a, b) => a + b, 0) / responseTimes.length;
  results.min = sorted[0];
  results.max = sorted[sorted.length - 1];
  results.stdDev = calculateStandardDeviation(responseTimes);

  return results;
}

function calculateStandardDeviation(values) {
  const avg = values.reduce((a, b) => a + b, 0) / values.length;
  const squareDiffs = values.map(value => Math.pow(value - avg, 2));
  const avgSquareDiff = squareDiffs.reduce((a, b) => a + b, 0) / squareDiffs.length;
  return Math.sqrt(avgSquareDiff);
}

