// MetricsCollection.java
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.DistributionSummary;
import org.springframework.stereotype.Component;

@Component
public class MetricsCollection {

    private final MeterRegistry registry;
    private final Timer requestTimer;
    private final Counter errorCounter;
    private final DistributionSummary responseSizeSummary;

    public MetricsCollection(MeterRegistry registry) {
        this.registry = registry;

        // Timer for request duration
        this.requestTimer = Timer.builder("api.request.duration")
            .description("API request duration")
            .publishPercentiles(0.5, 0.95, 0.99)
            .publishPercentileHistogram()
            .register(registry);

        // Counter for errors
        this.errorCounter = Counter.builder("api.errors")
            .description("API error count")
            .tag("type", "unhandled")
            .register(registry);

        // Distribution summary for response sizes
        this.responseSizeSummary = DistributionSummary.builder("api.response.size")
            .description("API response size in bytes")
            .baseUnit("bytes")
            .publishPercentiles(0.5, 0.95, 0.99)
            .register(registry);

        // Gauge for active threads
        registry.gauge("threadpool.active", 
            ThreadPoolMonitor.getActiveThreadCount());
    }

    public <T> T monitorRequest(String endpoint, Supplier<T> operation) {
        return requestTimer.record(() -> {
            try {
                T result = operation.get();
                // Record response size if applicable
                if (result instanceof String) {
                    responseSizeSummary.record(((String) result).getBytes().length);
                }
                return result;
            } catch (Exception e) {
                errorCounter.increment();
                registry.counter("api.errors", 
                    "endpoint", endpoint, 
                    "exception", e.getClass().getSimpleName()).increment();
                throw e;
            }
        });
    }

    public void recordDatabaseQuery(String query, long durationMs) {
        Timer.builder("database.query.duration")
            .tag("query", query.length() > 50 ? query.substring(0, 50) + "..." : query)
            .register(registry)
            .record(Duration.ofMillis(durationMs));
    }

    public void recordCacheHit(String cacheName) {
        registry.counter("cache.hits", "cache", cacheName).increment();
    }

    public void recordCacheMiss(String cacheName) {
        registry.counter("cache.misses", "cache", cacheName).increment();

        // Calculate hit rate
        double hits = registry.counter("cache.hits", "cache", cacheName).count();
        double misses = registry.counter("cache.misses", "cache", cacheName).count();
        double total = hits + misses;

        if (total > 0) {
            registry.gauge("cache.hit.rate", 
                tags("cache", cacheName), 
                hits / total);
        }
    }
}

