// ProfilingExample.java
import java.lang.management.*;
import java.util.concurrent.*;
import java.util.*;

public class ProfilingExample {

    private static final ScheduledExecutorService scheduler = 
        Executors.newScheduledThreadPool(1);

    public static void startProfilingCollector() {
        scheduler.scheduleAtFixedRate(() -> {
            collectMetrics();
        }, 0, 10, TimeUnit.SECONDS);
    }

    private static void collectMetrics() {
        // Get Thread MXBean
        ThreadMXBean threadBean = ManagementFactory.getThreadMXBean();

        // Get thread counts
        int threadCount = threadBean.getThreadCount();
        int peakThreadCount = threadBean.getPeakThreadCount();
        int daemonThreadCount = threadBean.getDaemonThreadCount();

        System.out.printf("Threads - Total: %d, Peak: %d, Daemon: %d%n",
            threadCount, peakThreadCount, daemonThreadCount);

        // Get deadlocked threads
        long[] deadlockedThreads = threadBean.findDeadlockedThreads();
        if (deadlockedThreads != null && deadlockedThreads.length > 0) {
            System.err.println("DEADLOCK DETECTED! Thread IDs: " + 
                Arrays.toString(deadlockedThreads));
        }

        // CPU time for each thread (if supported)
        if (threadBean.isThreadCpuTimeSupported()) {
            long[] allThreads = threadBean.getAllThreadIds();
            for (long tid : allThreads) {
                long cpuTime = threadBean.getThreadCpuTime(tid);
                long userTime = threadBean.getThreadUserTime(tid);
                if (cpuTime > 0) {
                    System.out.printf("Thread %d - CPU: %d ms, User: %d ms%n",
                        tid, cpuTime / 1_000_000, userTime / 1_000_000);
                }
            }
        }

        // Memory usage
        MemoryMXBean memoryBean = ManagementFactory.getMemoryMXBean();
        MemoryUsage heapUsage = memoryBean.getHeapMemoryUsage();
        MemoryUsage nonHeapUsage = memoryBean.getNonHeapMemoryUsage();

        System.out.printf("Heap - Used: %.2f MB, Max: %.2f MB, Usage: %.1f%%%n",
            heapUsage.getUsed() / (1024.0 * 1024.0),
            heapUsage.getMax() / (1024.0 * 1024.0),
            (heapUsage.getUsed() * 100.0) / heapUsage.getMax());

        // Garbage Collection
        List<GarbageCollectorMXBean> gcBeans = 
            ManagementFactory.getGarbageCollectorMXBeans();

        for (GarbageCollectorMXBean gc : gcBeans) {
            System.out.printf("GC %s - Collections: %d, Time: %d ms%n",
                gc.getName(), gc.getCollectionCount(), gc.getCollectionTime());
        }

        // Class loading
        ClassLoadingMXBean classBean = ManagementFactory.getClassLoadingMXBean();
        System.out.printf("Classes - Loaded: %d, Unloaded: %d, Total: %d%n",
            classBean.getLoadedClassCount(),
            classBean.getUnloadedClassCount(),
            classBean.getTotalLoadedClassCount());

        // Operating System
        OperatingSystemMXBean osBean = ManagementFactory.getOperatingSystemMXBean();
        System.out.printf("System Load: %.2f, CPUs: %d%n",
            osBean.getSystemLoadAverage(),
            osBean.getAvailableProcessors());
    }

    // Custom instrumentation for specific methods
    public static class MethodProfiler {
        private final Map<String, Long> methodTimes = new ConcurrentHashMap<>();
        private final Map<String, Long> methodCounts = new ConcurrentHashMap<>();

        public <T> T profile(String methodName, Supplier<T> operation) {
            long start = System.nanoTime();
            try {
                return operation.get();
            } finally {
                long duration = System.nanoTime() - start;
                methodTimes.merge(methodName, duration, Long::sum);
                methodCounts.merge(methodName, 1L, Long::sum);
            }
        }

        public void printStats() {
            System.out.println("\n=== Method Profiling Stats ===");
            for (String method : methodTimes.keySet()) {
                long totalTime = methodTimes.get(method);
                long count = methodCounts.get(method);
                double avgTime = totalTime / (double) count;

                System.out.printf("%s - Calls: %d, Total: %.2f ms, Avg: %.2f μs%n",
                    method, count,
                    totalTime / 1_000_000.0,
                    avgTime / 1000.0);
            }
        }
    }

    // Example usage
    public static void main(String[] args) {
        startProfilingCollector();

        MethodProfiler profiler = new MethodProfiler();

        // Profile some operations
        for (int i = 0; i < 100; i++) {
            int finalI = i;
            profiler.profile("compute", () -> {
                // Simulate work
                double result = 0;
                for (int j = 0; j < 10000; j++) {
                    result += Math.sin(finalI * j);
                }
                return result;
            });
        }

        profiler.printStats();

        // Keep running to collect metrics
        try {
            Thread.sleep(60000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

// DistributedTracing.java
import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.context.Scope;
import io.opentelemetry.exporter.jaeger.JaegerGrpcSpanExporter;
import io.opentelemetry.sdk.OpenTelemetrySdk;
import io.opentelemetry.sdk.trace.SdkTracerProvider;
import io.opentelemetry.sdk.trace.export.SimpleSpanProcessor;
import org.springframework.web.client.RestTemplate;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Service
public class DistributedTracingService {

    private final Tracer tracer;
    private final RestTemplate restTemplate;

    @Autowired
    public DistributedTracingService(RestTemplate restTemplate) {
        this.restTemplate = restTemplate;

        // Initialize OpenTelemetry with Jaeger exporter
        JaegerGrpcSpanExporter jaegerExporter = 
            JaegerGrpcSpanExporter.builder()
                .setEndpoint("http://jaeger:14250")
                .build();

        SdkTracerProvider tracerProvider = 
            SdkTracerProvider.builder()
                .addSpanProcessor(SimpleSpanProcessor.create(jaegerExporter))
                .build();

        OpenTelemetry openTelemetry = 
            OpenTelemetrySdk.builder()
                .setTracerProvider(tracerProvider)
                .build();

        this.tracer = openTelemetry.getTracer("performance-analysis");
    }

    public OrderResponse processOrder(OrderRequest request) {
        // Create root span for the entire operation
        Span rootSpan = tracer.spanBuilder("process-order")
            .setAttribute("order.id", request.getOrderId())
            .setAttribute("customer.id", request.getCustomerId())
            .startSpan();

        try (Scope scope = rootSpan.makeCurrent()) {

            // Step 1: Validate order (in-memory, fast)
            Span validationSpan = tracer.spanBuilder("validate-order")
                .setAttribute("order.items", request.getItems().size())
                .startSpan();
            try {
                validateOrder(request);
            } finally {
                validationSpan.end();
            }

            // Step 2: Check inventory (database call)
            Span inventorySpan = tracer.spanBuilder("check-inventory")
                .setAttribute("database.query", "SELECT quantity FROM inventory WHERE product_id = ?")
                .startSpan();
            try {
                checkInventory(request);
            } finally {
                inventorySpan.end();
            }

            // Step 3: Process payment (external service call)
            Span paymentSpan = tracer.spanBuilder("process-payment")
                .setAttribute("payment.provider", "stripe")
                .setAttribute("payment.amount", request.getTotalAmount())
                .startSpan();
            try {
                processPayment(request);
            } catch (Exception e) {
                paymentSpan.recordException(e);
                paymentSpan.setAttribute("error", true);
                throw e;
            } finally {
                paymentSpan.end();
            }

            // Step 4: Update order status (database write)
            Span updateSpan = tracer.spanBuilder("update-order-status")
                .setAttribute("order.status", "completed")
                .startSpan();
            try {
                updateOrderStatus(request);
            } finally {
                updateSpan.end();
            }

            // Step 5: Send notification (queue)
            Span notificationSpan = tracer.spanBuilder("send-notification")
                .setAttribute("notification.type", "email")
                .setAttribute("queue.name", "order-notifications")
                .startSpan();
            try {
                sendNotification(request);
            } finally {
                notificationSpan.end();
            }

            return buildResponse(request);

        } finally {
            rootSpan.end();
        }
    }

    private void checkInventory(OrderRequest request) {
        // Simulate database query
        long start = System.currentTimeMillis();
        // Database operation...
        long duration = System.currentTimeMillis() - start;

        // Record as event in current span
        Span.current().addEvent("database.query.completed", 
            Attributes.of(
                AttributeKey.longKey("duration_ms"), duration,
                AttributeKey.stringKey("query"), "inventory_check"
            )
        );
    }
}

// In a separate service for receiving traces
@RestController
class TraceAnalysisController {

    @GetMapping("/analyze-trace/{traceId}")
    public TraceAnalysis analyzeTrace(@PathVariable String traceId) {
        // Query Jaeger/Zipkin for trace data
        Trace trace = jaegerClient.getTrace(traceId);

        // Calculate time spent in each service
        Map<String, Long> serviceTimes = new HashMap<>();
        Map<String, Long> operationTimes = new HashMap<>();

        for (SpanData span : trace.getSpans()) {
            String serviceName = span.getServiceName();
            String operationName = span.getOperationName();
            long duration = span.getDuration().toMillis();

            serviceTimes.merge(serviceName, duration, Long::sum);
            operationTimes.merge(operationName, duration, Long::sum);
        }

        // Find critical path (longest chain of dependent spans)
        List<SpanData> criticalPath = findCriticalPath(trace);

        // Identify bottlenecks
        List<Bottleneck> bottlenecks = new ArrayList<>();
        for (Map.Entry<String, Long> entry : serviceTimes.entrySet()) {
            if (entry.getValue() > trace.getDuration().toMillis() * 0.3) {
                bottlenecks.add(new Bottleneck(
                    entry.getKey(),
                    entry.getValue(),
                    "Service accounts for >30% of total trace time"
                ));
            }
        }

        return new TraceAnalysis(traceId, serviceTimes, operationTimes, criticalPath, bottlenecks);
    }
}

