public class Author {
    @Id
    private Long id;
    private String name;
    private String email;

    // getters and setters
}

@Entity
public class Comment {
    @Id
    private Long id;
    private String text;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "article_id")
    private Article article;

    // getters and setters
}

// Repository with multiple fetch strategies
@Repository
public interface ArticleRepository extends JpaRepository<Article, Long> {

    // PROBLEM: N+1 queries
    // SELECT a FROM Article a WHERE a.published = true
    List<Article> findByPublishedTrue();

    // SOLUTION 1: JOIN FETCH
    @Query("SELECT DISTINCT a FROM Article a " +
           "LEFT JOIN FETCH a.author " +
           "LEFT JOIN FETCH a.comments " +
           "WHERE a.published = true")
    List<Article> findByPublishedTrueWithFetch();

    // SOLUTION 2: Entity Graph
    @EntityGraph(value = "article.with-author-and-comments", type = EntityGraph.EntityGraphType.FETCH)
    @Query("SELECT a FROM Article a WHERE a.published = true")
    List<Article> findByPublishedTrueWithEntityGraph();

    // SOLUTION 3: Batch fetching (configured in entity)
    // Just use regular query, @BatchSize handles it
    List<Article> findByPublishedTrue();
}

@Service
public class ArticleService {
    private final ArticleRepository articleRepository;

    public ArticleService(ArticleRepository articleRepository) {
        this.articleRepository = articleRepository;
    }

    // Before fix
    public List<ArticleDTO> getArticlesWithNPlusOne() {
        List<Article> articles = articleRepository.findByPublishedTrue();
        return articles.stream()
            .map(this::toDTO)
            .toList(); // This triggers N+1 queries
    }

    // After fix
    public List<ArticleDTO> getArticlesOptimized() {
        // Use join fetch version
        List<Article> articles = articleRepository.findByPublishedTrueWithFetch();

        // All data already loaded in single query
        return articles.stream()
            .map(this::toDTO)
            .toList();
    }

    // Alternative with entity graph
    public List<ArticleDTO> getArticlesWithEntityGraph() {
        List<Article> articles = articleRepository.findByPublishedTrueWithEntityGraph();
        return articles.stream()
            .map(this::toDTO)
            .toList();
    }

    private ArticleDTO toDTO(Article article) {
        // These getters now access already-loaded data
        return new ArticleDTO(
            article.getId(),
            article.getTitle(),
            article.getAuthor().getName(),  // No additional query
            article.getComments().stream()   // No additional query
                .map(Comment::getText)
                .toList()
        );
    }
}

