// JsonOptimization.java
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.annotation.JsonView;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

@Service
public class OptimizedJsonProcessor {

    // Single, properly configured ObjectMapper (thread-safe)
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
        .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false)
        .configure(JsonParser.Feature.AUTO_CLOSE_SOURCE, true)
        .configure(MapperFeature.DEFAULT_VIEW_INCLUSION, false);

    private final JsonFactory jsonFactory = new JsonFactory();

    // Before: Parsing entire JSON
    public DataRecord processFullJson(String jsonPayload) throws IOException {
        // Parses entire 10MB JSON
        return OBJECT_MAPPER.readValue(jsonPayload, DataRecord.class);
    }

    // After 1: Streaming parser - extract only needed fields
    public Map<String, Object> extractFieldsWithStreaming(String jsonPayload) throws IOException {
        Map<String, Object> result = new HashMap<>();

        try (JsonParser parser = jsonFactory.createParser(jsonPayload)) {
            // Fields we care about
            String[] neededFields = {"id", "name", "timestamp", "type"};

            while (parser.nextToken() != null) {
                if (parser.currentToken() == JsonToken.FIELD_NAME) {
                    String fieldName = parser.currentName();

                    // Check if this is a field we need
                    for (String needed : neededFields) {
                        if (needed.equals(fieldName)) {
                            parser.nextToken(); // Move to value

                            switch (parser.currentToken()) {
                                case VALUE_STRING:
                                    result.put(fieldName, parser.getText());
                                    break;
                                case VALUE_NUMBER_INT:
                                    result.put(fieldName, parser.getLongValue());
                                    break;
                                case VALUE_NUMBER_FLOAT:
                                    result.put(fieldName, parser.getDoubleValue());
                                    break;
                                case VALUE_TRUE:
                                case VALUE_FALSE:
                                    result.put(fieldName, parser.getBooleanValue());
                                    break;
                                default:
                                    // Skip or handle other types
                                    break;
                            }
                            break;
                        }
                    }
                }

                // Early exit if we have all fields
                if (result.size() == neededFields.length) {
                    break;
                }
            }
        }

        return result;
    }

    // After 2: Partial deserialization with views
    public interface SummaryView {}
    public interface DetailedView extends SummaryView {}

    @JsonView(SummaryView.class)
    public DataSummary processJsonSummary(String jsonPayload) throws IOException {
        // Only deserializes fields annotated with @JsonView(SummaryView.class)
        return OBJECT_MAPPER
            .readerWithView(SummaryView.class)
            .readValue(jsonPayload, DataSummary.class);
    }

    // After 3: Validate during parsing (single pass)
    public ValidationResult validateAndExtract(String jsonPayload) throws IOException {
        ValidationResult result = new ValidationResult();

        try (JsonParser parser = jsonFactory.createParser(jsonPayload)) {
            StringBuilder validationErrors = new StringBuilder();
            boolean hasRequiredFields = false;

            while (parser.nextToken() != null) {
                if (parser.currentToken() == JsonToken.FIELD_NAME) {
                    String fieldName = parser.currentName();
                    parser.nextToken(); // Move to value

                    // Validate as we parse
                    switch (fieldName) {
                        case "id":
                            if (parser.currentToken() != JsonToken.VALUE_NUMBER_INT) {
                                validationErrors.append("id must be integer; ");
                            } else {
                                result.setId(parser.getLongValue());
                                hasRequiredFields = true;
                            }
                            break;
                        case "name":
                            if (parser.currentToken() != JsonToken.VALUE_STRING) {
                                validationErrors.append("name must be string; ");
                            } else {
                                String name = parser.getText();
                                if (name.length() > 100) {
                                    validationErrors.append("name too long; ");
                                } else {
                                    result.setName(name);
                                }
                            }
                            break;
                        case "timestamp":
                            if (parser.currentToken() != JsonToken.VALUE_NUMBER_INT) {
                                validationErrors.append("timestamp must be number; ");
                            } else {
                                long ts = parser.getLongValue();
                                // Validate timestamp range
                                if (ts < 0 || ts > System.currentTimeMillis() + 86400000) {
                                    validationErrors.append("timestamp out of range; ");
                                } else {
                                    result.setTimestamp(ts);
                                }
                            }
                            break;
                    }
                }
            }

            if (!hasRequiredFields) {
                validationErrors.append("Missing required fields; ");
            }

            result.setValid(validationErrors.length() == 0);
            result.setErrors(validationErrors.toString());
        }

        return result;
    }

    // Performance comparison method
    public void benchmarkProcessing() throws IOException {
        String largeJson = generateLargeJson(10 * 1024 * 1024); // 10MB

        long start = System.nanoTime();
        processFullJson(largeJson);
        long fullTime = System.nanoTime() - start;

        start = System.nanoTime();
        extractFieldsWithStreaming(largeJson);
        long streamingTime = System.nanoTime() - start;

        System.out.printf("Full parse: %d ms%n", fullTime / 1_000_000);
        System.out.printf("Streaming: %d ms%n", streamingTime / 1_000_000);
        System.out.printf("Improvement: %.1fx%n", (double) fullTime / streamingTime);
    }
}

