// CodeOptimizations.java
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

public class CodeOptimizations {

    // ===== ALGORITHM OPTIMIZATION =====

    // Bad: O(n²) nested loops
    public List<User> findDuplicates_Bad(List<User> users) {
        List<User> duplicates = new ArrayList<>();
        for (int i = 0; i < users.size(); i++) {
            for (int j = i + 1; j < users.size(); j++) {
                if (users.get(i).getEmail().equals(users.get(j).getEmail())) {
                    duplicates.add(users.get(i));
                    break;
                }
            }
        }
        return duplicates;
    }

    // Good: O(n) with HashSet
    public List<User> findDuplicates_Good(List<User> users) {
        Set<String> emails = new HashSet<>();
        Set<String> duplicatesEmails = new HashSet<>();
        List<User> duplicates = new ArrayList<>();

        for (User user : users) {
            if (!emails.add(user.getEmail())) {
                // Email already seen
                if (duplicatesEmails.add(user.getEmail())) {
                    duplicates.add(user);
                }
            }
        }
        return duplicates;
    }

    // ===== CONCURRENCY OPTIMIZATION =====

    // Bad: Synchronizing entire method
    public synchronized void updateCounter_Bad(int value) {
        counter += value;
    }

    // Good: Atomic operation
    private AtomicInteger counter = new AtomicInteger();
    public void updateCounter_Good(int value) {
        counter.addAndGet(value);
    }

    // Bad: Heavy synchronization
    public class BadCache {
        private Map<String, Data> cache = new HashMap<>();

        public synchronized Data get(String key) {
            return cache.get(key);
        }

        public synchronized void put(String key, Data value) {
            cache.put(key, value);
        }
    }

    // Good: ConcurrentHashMap
    public class GoodCache {
        private ConcurrentMap<String, Data> cache = new ConcurrentHashMap<>();

        public Data get(String key) {
            return cache.get(key);
        }

        public Data put(String key, Data value) {
            return cache.put(key, value);
        }

        // Atomic put if absent
        public Data getOrCompute(String key, Function<String, Data> loader) {
            return cache.computeIfAbsent(key, loader);
        }
    }

    // ===== I/O OPTIMIZATION =====

    // Bad: Multiple database calls in loop
    public void processOrders_Bad(List<Order> orders) {
        for (Order order : orders) {
            User user = userRepository.findById(order.getUserId()); // N queries
            processOrder(order, user);
        }
    }

    // Good: Batch load
    public void processOrders_Good(List<Order> orders) {
        Set<Long> userIds = orders.stream()
            .map(Order::getUserId)
            .collect(Collectors.toSet());

        Map<Long, User> users = userRepository.findByIds(userIds) // 1 query
            .stream()
            .collect(Collectors.toMap(User::getId, Function.identity()));

        for (Order order : orders) {
            processOrder(order, users.get(order.getUserId()));
        }
    }

    // ===== MEMORY OPTIMIZATION =====

    // Bad: Creating many intermediate strings
    public String processData_Bad(String[] data) {
        String result = "";
        for (String s : data) {
            result += s + ","; // Creates new string each iteration
        }
        return result;
    }

    // Good: StringBuilder
    public String processData_Good(String[] data) {
        StringBuilder result = new StringBuilder();
        for (String s : data) {
            result.append(s).append(',');
        }
        return result.toString();
    }

    // Bad: Creating many small objects
    public List<Integer> parseIds_Bad(String[] idStrings) {
        List<Integer> ids = new ArrayList<>();
        for (String s : idStrings) {
            ids.add(Integer.parseInt(s)); // Creates Integer objects
        }
        return ids;
    }

    // Good: Use primitive arrays if possible
    public int[] parseIds_Good(String[] idStrings) {
        int[] ids = new int[idStrings.length];
        for (int i = 0; i < idStrings.length; i++) {
            ids[i] = Integer.parseInt(idStrings[i]);
        }
        return ids;
    }

    // ===== STREAM OPTIMIZATION =====

    // Bad: Multiple stream operations
    public List<String> processUsers_Bad(List<User> users) {
        return users.stream()
            .filter(u -> u.isActive())
            .collect(Collectors.toList())
            .stream()
            .map(User::getName)
            .collect(Collectors.toList());
    }

    // Good: Single stream pipeline
    public List<String> processUsers_Good(List<User> users) {
        return users.stream()
            .filter(User::isActive)
            .map(User::getName)
            .collect(Collectors.toList());
    }

    // ===== ASYNCHRONOUS PROCESSING =====

    private final ExecutorService executor = Executors.newFixedThreadPool(10);

    // Synchronous, blocking
    public void processSync(List<Work> works) {
        for (Work work : works) {
            processWork(work); // Blocks for each
        }
    }

    // Asynchronous, parallel
    public CompletableFuture<Void> processAsync(List<Work> works) {
        List<CompletableFuture<Void>> futures = works.stream()
            .map(work -> CompletableFuture.runAsync(() -> processWork(work), executor))
            .collect(Collectors.toList());

        return CompletableFuture.allOf(
            futures.toArray(new CompletableFuture[0])
        );
    }

    // ===== CACHING WITH EXPIRATION =====

    public class TimedCache<K, V> {
        private final Map<K, CacheEntry<V>> cache = new ConcurrentHashMap<>();
        private final long ttlMillis;

        public TimedCache(long ttlMillis) {
            this.ttlMillis = ttlMillis;
        }

        public V get(K key) {
            CacheEntry<V> entry = cache.get(key);
            if (entry != null && !entry.isExpired()) {
                return entry.value;
            }
            cache.remove(key);
            return null;
        }

        public void put(K key, V value) {
            cache.put(key, new CacheEntry<>(value, System.currentTimeMillis() + ttlMillis));
        }

        private static class CacheEntry<V> {
            final V value;
            final long expiry;

            CacheEntry(V value, long expiry) {
                this.value = value;
                this.expiry = expiry;
            }

            boolean isExpired() {
                return System.currentTimeMillis() > expiry;
            }
        }

        // Cleanup expired entries periodically
        @Scheduled(fixedDelay = 60000)
        public void cleanup() {
            cache.entrySet().removeIf(entry -> entry.getValue().isExpired());
        }
    }
}

