import java.sql.*;

public class UserDAO {

    // VULNERABLE METHOD: Direct concatenation of user input
    public User findUserByUsername_Vulnerable(String username) throws SQLException {
        String query = "SELECT * FROM users WHERE username = '" + username + "'";
        // Attacker input: "' OR '1'='1"
        // Resulting query: SELECT * FROM users WHERE username = '' OR '1'='1'
        // This returns ALL users!

        try (Statement stmt = connection.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {
            if (rs.next()) {
                return mapUser(rs);
            }
        }
        return null;
    }

    // SECURE METHOD: Using PreparedStatement (Parameterized Queries)
    public User findUserByUsername_Secure(String username) throws SQLException {
        String query = "SELECT * FROM users WHERE username = ?";

        try (PreparedStatement pstmt = connection.prepareStatement(query)) {
            pstmt.setString(1, username); // The input is treated as a STRING, not part of the SQL command

            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return mapUser(rs);
                }
            }
        }
        return null;
    }

    // Example of second-order SQLi (stored in DB, executed later)
    // Even with prepared statements, if you retrieve data from DB and concatenate it into another query, you can be vulnerable.
}

