from flask import Flask, request, jsonify, session, g
from functools import wraps
import logging

app = Flask(__name__)
logger = logging.getLogger(__name__)

# ===== CENTRALIZED AUTHORIZATION MIDDLEWARE =====

class AuthorizationMiddleware:
    """
    Centralized access control that can be applied to any endpoint.
    """

    @staticmethod
    def require_role(required_roles):
        """
        Decorator to require specific roles for an endpoint.
        """
        def decorator(f):
            @wraps(f)
            def decorated_function(*args, **kwargs):
                # Get user from session (or JWT, API key, etc.)
                user = session.get('user')
                if not user:
                    logger.warning(f"Unauthenticated access attempt to {request.path}")
                    return jsonify({'error': 'Authentication required'}), 401

                # Check if user's role is in allowed roles
                user_role = user.get('role')
                if user_role not in required_roles:
                    logger.warning(f"User {user.get('username')} with role {user_role} attempted to access {request.path}")
                    return jsonify({'error': 'Insufficient permissions'}), 403

                # Store user in request context for downstream use
                g.user = user
                return f(*args, **kwargs)
            return decorated_function
        return decorator

    @staticmethod
    def require_resource_ownership(resource_id_param='id', resource_type='user'):
        """
        Decorator to ensure the user owns the requested resource.
        """
        def decorator(f):
            @wraps(f)
            def decorated_function(*args, **kwargs):
                user = session.get('user')
                if not user:
                    return jsonify({'error': 'Authentication required'}), 401

                # Get the resource ID from URL parameters
                resource_id = kwargs.get(resource_id_param)

                # For admin users, maybe skip ownership check (but still log)
                if user.get('role') == 'admin':
                    logger.info(f"Admin {user.get('username')} accessing resource {resource_id}")
                    g.user = user
                    return f(*args, **kwargs)

                # Check if user owns this resource
                # This would typically query a database
                if not AuthorizationMiddleware._check_ownership(user.get('id'), resource_id, resource_type):
                    logger.warning(f"User {user.get('username')} attempted to access resource {resource_id} they don't own")
                    return jsonify({'error': 'Forbidden'}), 403

                g.user = user
                return f(*args, **kwargs)
            return decorated_function
        return decorator

    @staticmethod
    def _check_ownership(user_id, resource_id, resource_type):
        """
        Mock ownership check - in production, this would query the database.
        """
        # Example: Check if user_id owns resource_id in the database
        # SELECT COUNT(*) FROM resources WHERE id = resource_id AND owner_id = user_id
        # For demo, assume user 1 owns resource 100, user 2 owns resource 200
        ownership_map = {
            (1, 100): True,
            (2, 200): True,
        }
        return ownership_map.get((user_id, int(resource_id)), False)


# ===== API ENDPOINTS WITH CENTRALIZED ACCESS CONTROL =====

@app.route('/api/users/<int:user_id>', methods=['GET'])
@AuthorizationMiddleware.require_resource_ownership('user_id', 'user')
def get_user(user_id):
    """
    User can only access their own profile due to ownership check.
    Admins can access any profile (handled in middleware).
    """
    # This code only executes if authorization passed
    user = g.user
    return jsonify({
        'id': user_id,
        'username': user.get('username'),
        'email': user.get('email'),
        'role': user.get('role')
    })


