import secrets
import hmac
import hashlib
from functools import wraps
from flask import Flask, session, request, render_template_string, abort, make_response

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)  # Use a strong secret key

# ===== METHOD 1: Synchronizer Token Pattern =====

class CSRFProtection:
    @staticmethod
    def generate_token():
        """Generate a cryptographically secure random token"""
        return secrets.token_urlsafe(32)

    @staticmethod
    def store_token():
        """Store token in session"""
        if 'csrf_token' not in session:
            session['csrf_token'] = CSRFProtection.generate_token()
        return session['csrf_token']

    @staticmethod
    def validate_token(token):
        """Validate token against session"""
        if not token:
            return False
        stored_token = session.get('csrf_token')
        if not stored_token:
            return False
        # Use constant-time comparison to prevent timing attacks
        return hmac.compare_digest(stored_token, token)


def csrf_protect(f):
    """Decorator to require CSRF token for POST requests"""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if request.method == 'POST':
            token = request.form.get('csrf_token') or request.headers.get('X-CSRF-Token')
            if not CSRFProtection.validate_token(token):
                abort(403, description="CSRF token missing or invalid")
        return f(*args, **kwargs)
    return decorated_function


@app.context_processor
def inject_csrf_token():
    """Make CSRF token available in all templates"""
    return dict(csrf_token=CSRFProtection.store_token())


# ===== METHOD 2: Double Submit Cookie Pattern =====
# Token stored in cookie AND submitted as parameter

class DoubleSubmitCSRF:
    @staticmethod
    def generate_token():
        return secrets.token_urlsafe(32)

    @staticmethod
    def set_cookie_token(response):
        token = DoubleSubmitCSRF.generate_token()
        response.set_cookie('csrf_token', token, httponly=False, samesite='Strict', secure=True)
        return token

    @staticmethod
    def validate(cookie_token, param_token):
        if not cookie_token or not param_token:
            return False
        return hmac.compare_digest(cookie_token, param_token)


@app.route('/transfer-double', methods=['GET', 'POST'])
def transfer_double():
    if request.method == 'POST':
        cookie_token = request.cookies.get('csrf_token')
        param_token = request.form.get('csrf_token')

        if not DoubleSubmitCSRF.validate(cookie_token, param_token):
            abort(403, description="CSRF validation failed")

        # Process transfer...
        return "Transfer successful"

    # GET request - show form
    response = make_response(render_template_string('''
