# ===== DEFENSE 4: Signed Double Submit Cookie =====

class SignedDoubleSubmitCSRF:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def generate_token(self, session_id):
        """Generate a signed token"""
        timestamp = str(int(time.time()))
        payload = f"{session_id}:{timestamp}"
        signature = hmac.new(
            self.secret_key.encode(),
            payload.encode(),
            hashlib.sha256
        ).hexdigest()
        return f"{payload}:{signature}"

    def validate_token(self, token, session_id):
        """Validate signed token"""
        try:
            parts = token.split(':')
            if len(parts) != 3:
                return False

            token_session_id, timestamp, signature = parts

            # Check session ID matches
            if token_session_id != session_id:
                return False

            # Check expiration (optional)
            if int(timestamp) < time.time() - 3600:  # 1 hour expiry
                return False

            # Verify signature
            expected_payload = f"{token_session_id}:{timestamp}"
            expected_signature = hmac.new(
                self.secret_key.encode(),
                expected_payload.encode(),
                hashlib.sha256
            ).hexdigest()

            return hmac.compare_digest(signature, expected_signature)
        except Exception:
            return False

