# Step 4: Test for field-level authorization bypass.
# Query a public object (e.g., a specific post) but request an admin-only field on it.
query FieldLevelBypass {
  post(id: "public-post-123") {
    title
    content
    author {
      email  # This might be considered private for non-admins
      lastLoginIP # Definitely an admin-only field
    }
  }
}

# Vulnerable Response: The response includes `email` and `lastLoginIP`.
# Secure Response: Those fields return null, or an error is raised.

// authz.js - Centralized authorization logic

// Define permissions (RBAC example)
const permissions = {
    user: {
        'read:own:profile': true,
        'update:own:profile': true,
        'read:public:posts': true,
    },
    editor: {
        'read:own:profile': true,
        'update:own:profile': true,
        'read:public:posts': true,
        'create:post': true,
        'update:any:post': true,
    },
    admin: {
        '*': true // Admin can do everything
    }
};

// Middleware factory
function authorize(permission, resourceFetcher) {
    return async (req, res, next) => {
        const user = req.user; // Set by authentication middleware
        if (!user) {
            return res.status(401).json({ error: 'Unauthenticated' });
        }

        // 1. Check role-based permission
        const userPerms = permissions[user.role] || {};
        const hasRolePermission = userPerms[permission] || userPerms['*'];

        if (!hasRolePermission) {
            return res.status(403).json({ error: 'Forbidden: Insufficient role' });
        }

        // 2. Check object-level ownership if a resource fetcher is provided
        if (resourceFetcher) {
            try {
                const resource = await resourceFetcher(req);
                if (!resource) {
                    return res.status(404).json({ error: 'Resource not found' });
                }

                // Ownership logic: Can the user access this specific resource?
                // This checks if the permission implies 'own' or 'any'
                const isOwnAction = permission.includes(':own:');
                if (isOwnAction) {
                    if (resource.userId !== user.id) {
                        return res.status(403).json({ error: 'Forbidden: Resource does not belong to user' });
                    }
                }
                // If permission is for 'any', the role check already passed, so we're good.
                // Attach resource to request for the route handler
                req.resource = resource;
            } catch (error) {
                return res.status(500).json({ error: 'Error fetching resource' });
            }
        }

        next();
    };
}

module.exports = authorize;


