const express = require('express');
const authorize = require('./authz');
const router = express.Router();

// Example: Update own profile
router.put('/profile', 
    authorize('update:own:profile'), // No resource fetcher needed, user is the resource
    async (req, res) => {
        // Update logic - user is req.user
        res.json({ message: 'Profile updated' });
    }
);

